CREATE DATABASE IF NOT EXISTS codecraft CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE codecraft;
CREATE TABLE IF NOT EXISTS projects (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,category VARCHAR(80) NOT NULL,client VARCHAR(180) NOT NULL,year VARCHAR(10) NOT NULL,duration VARCHAR(80) NOT NULL,description TEXT NOT NULL,long_description LONGTEXT NULL,image MEDIUMTEXT NULL,technologies JSON NULL,results JSON NULL,published BOOLEAN NOT NULL DEFAULT TRUE,featured BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS contact_messages (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,email VARCHAR(255) NOT NULL,message TEXT NOT NULL,service VARCHAR(120) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quote_requests (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,email VARCHAR(255) NOT NULL,company VARCHAR(180) NULL,service VARCHAR(120) NOT NULL,budget VARCHAR(80) NULL,details TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS job_applications (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,email VARCHAR(255) NOT NULL,job_title VARCHAR(180) NULL,resume_url TEXT NULL,message TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
